{
  description = "Kasiro's NixOS configuration";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-26.05";
    nixpkgs-unstable.url = "github:NixOS/nixpkgs/nixos-unstable";
    home-manager = {
      url = "github:nix-community/home-manager/release-26.05";
      inputs.nixpkgs.follows = "nixpkgs";
    };
    # Upstream opencode — точная версия мимо nixpkgs (там всегда лаг на несколько дней)
    aicode = {
      url = "github:anomalyco/opencode/v1.18.32";
      inputs.nixpkgs.follows = "nixpkgs-unstable";
    };
  };

  outputs = { self, nixpkgs, nixpkgs-unstable, aicode, home-manager, ... }:
    let
      system = "x86_64-linux";

# Kasiro user-specific configuration
{ config, pkgs, ... }:

{
  # User account
  users.users.kasiro = {
    isNormalUser = true;
    description = "kasiro";
    extraGroups = [ "networkmanager" "wheel" "docker" ];

  };

  # User packages
  environment.systemPackages = with pkgs; [
    nodejs
    python3
    uv
    wl-clipboard
    gnome-extension-manager
    chromium

{ config, pkgs, lib, ... }: {
  home.username = "kasiro";
  home.homeDirectory = "/home/kasiro";
  home.stateVersion = "26.05";

  # Пакеты для kasiro
  home.packages = with pkgs; [
    bibata-cursors
  ];

  # dconf настройки GNOME (применяются без перелогина через home-manager switch)
  dconf.settings = {
    # GNOME Shell - расширения
    "org/gnome/shell" = {
      disable-user-extensions = false;
      enabled-extensions = [
        "appindicatorsupport@rgcjonas.gmail.com"
        "dash-to-dock@micxgx.gmail.com"
        "blur-my-shell@aunetx"
        "caffeine@patapon.info"

