      url = "github:nix-community/home-manager/release-26.05";
      inputs.nixpkgs.follows = "nixpkgs";
    };
  };

  outputs = { self, nixpkgs, nixpkgs-unstable, home-manager, ... }:
    let
      system = "x86_64-linux";
      pkgs-unstable = nixpkgs-unstable.legacyPackages.${system};
    in {
      nixosConfigurations.nixos = nixpkgs.lib.nixosSystem {
        inherit system;
        modules = [
          ./configuration.nix
          home-manager.nixosModules.home-manager
          {
            _module.args.pkgs-unstable = pkgs-unstable;
            nixpkgs.overlays = [
              (final: prev: {
                opencode = pkgs-unstable.opencode;
              })
            ];
            home-manager.users.kasiro = import ./home/kasiro.nix;
            home-manager.users.whitepeach = import ./home/whitepeach.nix;
          }
        ];
      };

      homeConfigurations.kasiro = home-manager.lib.homeManagerConfiguration {
        pkgs = nixpkgs.legacyPackages.x86_64-linux;
        modules = [ ./home/kasiro.nix ];
      };

      homeConfigurations.whitepeach = home-manager.lib.homeManagerConfiguration {
        pkgs = nixpkgs.legacyPackages.x86_64-linux;
        modules = [ ./home/whitepeach.nix ];
      };
    };
}

