# System services configuration
{ config, pkgs, lib, ... }:

{
  # Networking
  networking.networkmanager.enable = true;

  # NetworkManager connectivity check — fixes "?" icon after relogin
  environment.etc."NetworkManager/conf.d/20-connectivity.conf".text = ''
    [connectivity]
    uri=http://nmcheck.gnome.org/check_network_status.txt
  '';

  # Printing
  services.printing.enable = true;

  # Sound via PipeWire
  security.rtkit.enable = true;
  services.pipewire = {
    enable = true;
    alsa.enable = true;
    alsa.support32Bit = true;
    pulse.enable = true;
  };

  # Firefox browser
  programs.firefox.enable = true;

  # Allow dynamically linked executables
  programs.nix-ld.enable = true;

  # Docker containerization
  virtualisation.docker.enable = true;

  # Steam gaming
  programs.steam = {
    enable = true;
    remotePlay.openFirewall = true;
    dedicatedServer.openFirewall = true;
  };
  programs.gamemode.enable = true;

  # ydotool — эмуляция ввода
  programs.ydotool.enable = true;

  # System packages available to all users
  environment.systemPackages = with pkgs; [
    git
    jq
    micro
    neovim
    obsidian
    telegram-desktop

    # GNOME extensions — все 10 штук
    gnomeExtensions.appindicator
    gnomeExtensions.dash-to-dock
    gnomeExtensions.blur-my-shell
    gnomeExtensions.caffeine
    gnomeExtensions.tophat
    gnomeExtensions.clipboard-history
    gnomeExtensions.window-calls
    gnomeExtensions.app-hider
    opencode
  ];
}

